/**
 * World Food Programme (WFP) Bangladesh Food Prices Dataset (2024 - 2026)
 * Grounded Market Prices from 3628 Real Observations across 8 Divisions and 118 Markets
 */

export interface WFPPriceObservation {
  id: string;
  commodity: string;
  name: string;
  nameBn: string;
  category: string;
  division: string;
  divisionBn: string;
  district: string;
  market: string;
  marketId: string;
  price: number;
  unit: string;
  packSize: string;
  trend: 'up' | 'down' | 'stable';
  change: string;
  observedAt: string;
  year: string;
  seller: string;
  source: string;
  latitude: string;
  longitude: string;
}

